-- Actualiza seed landing pages a HTML con formulario simulado + tracking JS
-- Los formularios muestran campos decorativos (valores fijos), nunca capturan credenciales reales
UPDATE landing_pages SET html = '<html><body style=''font-family:Arial,sans-serif;margin:0;background:#f0f2f5''><div style=''max-width:400px;margin:60px auto;background:#fff;padding:30px;border-radius:8px;box-shadow:0 2px 10px rgba(0,0,0,.15)''><h2 style=''margin-top:0;color:#333''>Verificacion de cuenta</h2><p style=''color:#555''>Su sesion ha expirado. Verifique sus datos para continuar.</p><form id=''sim-form''><input type=''text'' placeholder=''Usuario'' value=''demo'' style=''width:100%;padding:10px;margin:8px 0;box-sizing:border-box''><input type=''password'' placeholder=''Contrasena'' value=''********'' style=''width:100%;padding:10px;margin:8px 0;box-sizing:border-box''><button type=''submit'' style=''width:100%;padding:12px;background:#1a73e8;color:#fff;border:none;border-radius:4px;cursor:pointer''>Iniciar sesion</button></form></div><script>(function(){var f=document.getElementById(''sim-form'');f.addEventListener(''submit'',function(e){e.preventDefault();fetch(''/api/v1/tracking/{{TOKEN}}/submit'',{method:''POST''}).then(function(){window.location.href=''/training/{{SLUG}}?token={{TOKEN}}'';});});})();</script></body></html>' WHERE slug = 'corporate-login' AND active = 1;

UPDATE landing_pages SET html = '<html><body style=''font-family:Arial,sans-serif;margin:0;background:#f0f2f5''><div style=''max-width:420px;margin:60px auto;background:#fff;padding:30px;border-radius:8px;box-shadow:0 2px 10px rgba(0,0,0,.15)''><h2 style=''margin-top:0;color:#333''>Documento compartido</h2><p style=''color:#555''>Un usuario compartio un documento contigo en OneDrive.</p><button id=''sim-form'' style=''width:100%;padding:12px;background:#28a745;color:#fff;border:none;border-radius:4px;cursor:pointer''>Descargar documento</button></div><script>(function(){var f=document.getElementById(''sim-form'');f.addEventListener(''click'',function(e){fetch(''/api/v1/tracking/{{TOKEN}}/submit'',{method:''POST''}).then(function(){window.location.href=''/training/{{SLUG}}?token={{TOKEN}}'';});});})();</script></body></html>' WHERE slug = 'onedrive-document' AND active = 1;

UPDATE landing_pages SET html = '<html><body style=''font-family:Arial,sans-serif;margin:0;background:#f0f2f5''><div style=''max-width:400px;margin:60px auto;background:#fff;padding:30px;border-radius:8px;box-shadow:0 2px 10px rgba(0,0,0,.15)''><h2 style=''margin-top:0;color:#d93025''>Alerta de seguridad</h2><p style=''color:#555''>Detectamos actividad inusual. Verifique su identidad para reactivar la cuenta.</p><form id=''sim-form''><input type=''text'' placeholder=''Usuario'' value=''demo'' style=''width:100%;padding:10px;margin:8px 0;box-sizing:border-box''><input type=''password'' placeholder=''Contrasena'' value=''********'' style=''width:100%;padding:10px;margin:8px 0;box-sizing:border-box''><button type=''submit'' style=''width:100%;padding:12px;background:#d93025;color:#fff;border:none;border-radius:4px;cursor:pointer''>Verificar cuenta</button></form></div><script>(function(){var f=document.getElementById(''sim-form'');f.addEventListener(''submit'',function(e){e.preventDefault();fetch(''/api/v1/tracking/{{TOKEN}}/submit'',{method:''POST''}).then(function(){window.location.href=''/training/{{SLUG}}?token={{TOKEN}}'';});});})();</script></body></html>' WHERE slug = 'security-alert' AND active = 1;